void sensor_proto_tx_tsk( void )
{
    Sensor_Proto_Tx_Frame *frame ; 

    for( ; ; )
    {
        frame = (Sensor_Proto_Tx_Frame *) q_remove( sensor_proto_tx_q_pending , 0 ) ;   
        
        wake_enter_flagged(WAKE_SENS_PROTO_TX);
        {
            intl_port_sensor_proto_req(frame->pld, frame->pld_size );
                
            q_return( (Q_Msg*)frame );
        }
        wake_leave_flagged(WAKE_SENS_PROTO_TX) ;
    };
}
